{"code": "export async function main(input: unknown) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });
  const filtered = res.issues.filter(i => i.status === "unresolved" && i.count >= 100);
  return { total: res.issues.length, filtered: filtered.map(i => ({ shortId: i.shortId, title: i.title, culprit: i.culprit, count: i.count, status: i.status, project: i.project })) };
}"}

{"code": "export async function main(input: unknown) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });
  const filtered = res.issues.filter(i => i.status === "unresolved" && i.count >= 100);
  const out: any[] = [];
  for (const i of filtered) {
    const found = await sdk.linear.searchIssues({ query: `[Sentry] ${i.shortId}` });
    out.push({ shortId: i.shortId, matches: found.issues.map(x => ({ identifier: x.identifier, title: x.title, state: x.state })) });
  }
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const res = await sdk.sentry.listIssues({ project: "jobs" });
  const filtered = res.issues.filter(i => i.status === "unresolved" && i.count >= 100);
  const created: any[] = [];
  for (const i of filtered) {
    const title = `[Sentry] ${i.shortId}`;
    const existing = await sdk.linear.searchIssues({ query: title });
    const dup = existing.issues.filter(x => x.title === title);
    if (dup.length > 0) {
      created.push({ shortId: i.shortId, skipped: dup.map(d => d.identifier) });
      continue;
    }
    const ph = await sdk.linear.createIssue({ title, description: i.culprit });
    created.push({ shortId: i.shortId, title, description: i.culprit, created: ph });
  }
  return created;
}"}
